pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient, uint256 amount) public {
        if(recipient == address(0)) recipient = address(1);
        uint256 before = c.proposalCount();
        address caller = address(0xBEEF);
        vm.prank(caller);
        c.newGrantProposal(recipient, amount);
        uint256 afterCount = c.proposalCount();
        assertTrue(afterCount == before + 1);
    }
}
